def annotations():
    rows = {}
    for line in ANNOTATIONS.splitlines():
        key, code, working, result, fact = line.split('|')
        if key in rows:
            raise ValueError('Duplicate ticket annotation: ' + key)
        rows[key] = dict(code=code, working=working, result=result, result_fact=fact)
    if len(rows) != 96:
        raise ValueError('Expected 96 classifier/response annotations')
    return rows


